import{_ as s,o as a,c as n,a2 as t}from"./chunks/framework.DGOtNzMU.js";const u=JSON.parse('{"title":"Project structure","description":"","frontmatter":{},"headers":[],"relativePath":"guide/project-structure.md","filePath":"guide/project-structure.md","lastUpdated":1795697360000}'),o={name:"guide/project-structure.md"};function i(p,e,r,l,d,c){return a(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="project-structure" tabindex="-1">Project structure <a class="header-anchor" href="#project-structure" aria-label="Permalink to &quot;Project structure&quot;">​</a></h1><p>What goes where in a ktor-svelte project, and which files are yours to edit.</p><p>A project created by the <a href="./getting-started">setup script</a> looks like the tree below. Projects that add ktor-svelte to an existing app have the same core: a Gradle build with the plugin, a Ktor app with <code>install(Svelte)</code>, and a SvelteKit app in <code>frontend/</code>.</p><h2 id="the-tree" tabindex="-1">The tree <a class="header-anchor" href="#the-tree" aria-label="Permalink to &quot;The tree&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-app/</span></span>
<span class="line"><span>  build.gradle.kts            plugins, svelte { } settings, dependencies</span></span>
<span class="line"><span>  settings.gradle.kts</span></span>
<span class="line"><span>  gradle.properties</span></span>
<span class="line"><span>  gradle/libs.versions.toml   version catalog</span></span>
<span class="line"><span>  gradlew, gradlew.bat        Gradle wrapper</span></span>
<span class="line"><span>  src/main/kotlin/</span></span>
<span class="line"><span>    Application.kt            embeddedServer, install(Svelte), routes</span></span>
<span class="line"><span>    Env.kt                    env() and requireEnv(), reading the environment and .env</span></span>
<span class="line"><span>    Errors.kt                 typed error responses</span></span>
<span class="line"><span>    Auth.kt                   if you chose sign in</span></span>
<span class="line"><span>    Database.kt               if you chose Postgres</span></span>
<span class="line"><span>  src/main/resources/</span></span>
<span class="line"><span>    logback.xml</span></span>
<span class="line"><span>    db/migration/             if you chose Flyway</span></span>
<span class="line"><span>  frontend/</span></span>
<span class="line"><span>    package.json</span></span>
<span class="line"><span>    vite.config.ts            generated by ktor-svelte</span></span>
<span class="line"><span>    vite.user.ts              your own Vite settings, if you need any</span></span>
<span class="line"><span>    messages/                 i18n message files, if i18n is on</span></span>
<span class="line"><span>    src/</span></span>
<span class="line"><span>      app.html</span></span>
<span class="line"><span>      routes/                 your pages</span></span>
<span class="line"><span>      lib/api/                generated TypeScript client</span></span>
<span class="line"><span>      lib/ktor-svelte/        generated helpers for themes, icons, i18n and more</span></span>
<span class="line"><span>  .run/                       IntelliJ run configurations</span></span>
<span class="line"><span>  .env.example                every variable the app reads</span></span>
<span class="line"><span>  .env                        local secrets, if you chose sign in or Postgres; not committed</span></span>
<span class="line"><span>  compose.yaml                if you chose Postgres</span></span>
<span class="line"><span>  Dockerfile                  if you chose Docker</span></span>
<span class="line"><span>  .github/workflows/ci.yml    if you chose GitHub Actions</span></span>
<span class="line"><span>  .github/workflows/release.yml, release-please-config.json, version.txt</span></span>
<span class="line"><span>                              if you chose release-please</span></span>
<span class="line"><span>  .githooks/commit-msg        if you chose Conventional Commits</span></span>
<span class="line"><span>  .github/dependabot.yml      if you chose Dependabot</span></span>
<span class="line"><span>  .railway/railway.ts         if you chose Railway, with .github/workflows/deploy.yml</span></span>
<span class="line"><span>  AGENTS.md, CLAUDE.md        if you chose agentic usage</span></span>
<span class="line"><span>  .claude/settings.json       if you chose agentic usage</span></span>
<span class="line"><span>  build-logic/                if you chose the convention plugin or hexagonal modules</span></span>
<span class="line"><span>  orders/                     a bounded context, if you chose hexagonal modules</span></span>
<span class="line"><span>    domain/                   the aggregate and its rules</span></span>
<span class="line"><span>    application/              use cases and ports</span></span>
<span class="line"><span>    adapters/                 HTTP routes and the repository</span></span>
<span class="line"><span>  shared-kernel/              if you chose a shared kernel</span></span>
<span class="line"><span>  README.md</span></span></code></pre></div><p>With <code>--no-idea-ext</code>, the Kotlin files sit in package folders, such as <code>src/main/kotlin/com/example/app/</code>, instead of directly in <code>src/main/kotlin</code>. The modules of a bounded context always use package folders, such as <code>orders/domain/src/main/kotlin/com/example/app/orders/domain/</code>. With <code>--module-layout=single</code>, each context is one folder with those three packages instead of three modules.</p><h2 id="files-you-own-and-files-ktor-svelte-owns" tabindex="-1">Files you own and files ktor-svelte owns <a class="header-anchor" href="#files-you-own-and-files-ktor-svelte-owns" aria-label="Permalink to &quot;Files you own and files ktor-svelte owns&quot;">​</a></h2><p>ktor-svelte writes some files for you and keeps them up to date. Each of them starts with a &quot;Generated by ktor-svelte&quot; header, and the line after it links to the docs page that explains the file, so a teammate who opens it knows where to look. The files in <code>src/lib/api</code> have no header of their own; their <code>.gitattributes</code> carries it instead.</p><div class="warning custom-block"><p class="custom-block-title">Do not edit generated files</p><p>The next sync or start overwrites your changes.</p></div><table tabindex="0"><thead><tr><th>File</th><th>Written by</th><th>Changes when</th></tr></thead><tbody><tr><td><code>frontend/src/lib/api/*</code></td><td>the app in development, or <code>svelteGenerateTs</code></td><td>a route or DTO changes</td></tr><tr><td><code>frontend/vite.config.ts</code></td><td><code>svelteSync</code></td><td>library settings change</td></tr><tr><td><code>frontend/src/lib/ktor-svelte/*</code></td><td><code>svelteSync</code></td><td>themes, icons or locales change</td></tr><tr><td><code>frontend/src/hooks*.ts</code></td><td><code>svelteSync</code></td><td>i18n or theme settings change</td></tr><tr><td>Kotlin <code>AppTheme</code>, <code>AppLanguage</code> and <code>Messages</code> classes</td><td>the Gradle build, in <code>build/generated</code>, never committed</td><td>themes, locales or messages change</td></tr></tbody></table><p>Everything else is yours. ktor-svelte never overwrites a file without the header. If it needs to own a file you already have, such as your own <code>vite.config.ts</code>, the build stops and tells you what to move. Put custom Vite settings in <code>vite.user.ts</code>.</p><h3 id="commit-the-generated-files" tabindex="-1">Commit the generated files <a class="header-anchor" href="#commit-the-generated-files" aria-label="Permalink to &quot;Commit the generated files&quot;">​</a></h3><p>Commit the generated frontend files. That way:</p><ul><li>a frontend build never needs the JVM app to run first,</li><li><code>svelteVerifyTs</code> and <code>svelteVerifySync</code> in <code>check</code> fail when they are out of date, so a changed DTO cannot drift away from the frontend unnoticed.</li></ul><p>Each generated folder also gets a <code>.gitattributes</code> that marks its files as generated. <a href="./../reference/gradle#generated-files-without-merge-conflicts">Generated files without merge conflicts</a> shows how to keep two branches from fighting over them.</p><h2 id="the-api-import" tabindex="-1">The <code>#api</code> import <a class="header-anchor" href="#the-api-import" aria-label="Permalink to &quot;The \`#api\` import&quot;">​</a></h2><p><code>svelteInit</code> and <code>svelteSync</code> add an import alias to <code>frontend/package.json</code>, so pages import the generated client the same way wherever they are:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { api, isApiError, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Note } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;#api&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>Libraries add their own short imports next to it, such as <code>#routes</code> for <a href="./../features/routes">typed routes</a> and <code>#components/...</code> for the <a href="./../features/components">ready-made components</a>.</p><h2 id="what-ends-up-in-the-jar" tabindex="-1">What ends up in the JAR <a class="header-anchor" href="#what-ends-up-in-the-jar" aria-label="Permalink to &quot;What ends up in the JAR&quot;">​</a></h2><p><code>svelteBundle</code> copies the static build into <code>ktor-svelte/public/</code> in your resources and writes <code>ktor-svelte/manifest.json</code>. Hidden files such as <code>.env</code> and source maps are left out. The <a href="./../reference/how-it-works">How it works</a> page explains how requests are answered from the manifest.</p>`,21)])])}const g=s(o,[["render",i]]);export{u as __pageData,g as default};
